lookup = {'not': [1., 0.], 'good': [0., 1.]}
kernel = np.array([[1., 0.], [0., 1.]])
def encode(text):
    return np.array([lookup.get(word, [0., 0.]) for word in text.split()])

first = encode('not good food')
shifted = encode('the food is not good')
assert first.shape == (3, 2)
assert shifted.shape == (5, 2)
print('Размеры двух отзывов:', first.shape, shifted.shape)

def activation(encoded):
    if len(encoded) < 2:
        return np.array([], dtype=float)
    return np.array([np.sum(encoded[i:i + 2] * kernel)
                     for i in range(len(encoded) - 1)])
def pooled(encoded):
    return float(activation(encoded).max(initial=0))

scores_first = activation(first)
scores_shifted = activation(shifted)
assert np.argmax(scores_first) == 0
assert np.argmax(scores_shifted) == 3
assert pooled(first) == pooled(shifted) == 2
print('Позиции пиков:', np.argmax(scores_first), np.argmax(scores_shifted))
